{
  "investigate": [
    {
      "tool": "logs",
      "service": "worker",
      "level": "ERROR",
      "contains": "disk quota exceeded",
      "why": "To check if the disk quota error is for a specific path or mount point that might be shared, since the storage table shows ample quota for worker and sync-job individually."
    }
  ],
  "hypotheses": [
    {
      "service": "worker",
      "kind": "resource_exhaustion",
      "mechanism": "A shared disk or temporary file system used by worker for invoice file writes is exhausted, despite individual service quotas being fine.",
      "supporting": ["E13", "E15", "E2", "E4", "E7", "E8", "E9"],
      "refuting": ["E30"],
      "explains": ["M2_error_burst", "M3_dead_letters", "E5", "E10", "E11", "E12"],
      "repair_plan": [
        {"action": "restart_service", "params": {"service": "worker"}}
      ]
    },
    {
      "service": "sync-job",
      "kind": "resource_exhaustion",
      "mechanism": "A shared disk or temporary file system used by sync-job for ledger exports is exhausted, despite individual service quotas being fine.",
      "supporting": ["E14", "E3", "E6"],
      "refuting": ["E30"],
      "explains": ["E3", "E6"],
      "repair_plan": [
        {"action": "restart_service", "params": {"service": "sync-job"}}
      ]
    }
  ],
  "summary": "Disk quota errors point to a shared storage exhaustion affecting worker and sync-job, not captured by individual service quotas."
}
